function ai_encryption_key():string{$secret=(string)getenv('SHULELITE_ENCRYPTION_KEY');if(strlen($secret)<32)throw new RuntimeException('The server administrator must configure SHULELITE_ENCRYPTION_KEY with a random secret of at least 32 characters before saving provider keys.');return hash('sha256',$secret,true);}
function ai_encrypt_secret(string $value):string{$nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt($value,'aes-256-gcm',ai_encryption_key(),OPENSSL_RAW_DATA,$nonce,$tag,'ShuleLite OpenRouter API key');if($cipher===false)throw new RuntimeException('OpenRouter API key encryption failed.');return base64_encode($nonce.$tag.$cipher);}
function ai_decrypt_secret(string $value):string{$raw=base64_decode($value,true);if($raw===false||strlen($raw)<=28)throw new RuntimeException('Saved provider key is unavailable. Save a new OpenRouter key.');$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',ai_encryption_key(),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),'ShuleLite OpenRouter API key');if($plain===false)throw new RuntimeException('Saved provider key could not be decrypted. Check SHULELITE_ENCRYPTION_KEY.');return $plain;}
function ai_question_model_chain():array{return ['openai/gpt-4o-mini','~anthropic/claude-haiku-latest','google/gemini-3.8-flash','~moonshotai/kimi-latest','~z-ai/glm-latest'];}
function ai_teacher_notes(PDO $pdo,int $uid,?string $class=null,?string $subject=null):array{$sql="SELECT DISTINCT n.id,n.subtopic,n.class_level,n.subject,n.topic,n.content,n.source,n.note_type FROM learning_notes n WHERE n.status='published' AND ((n.note_type='teacher' AND EXISTS(SELECT 1 FROM teacher_assignments a JOIN school_memberships m ON m.school_id=a.school_id AND m.user_id=a.user_id WHERE a.user_id=? AND a.active=1 AND a.school_id=n.school_id AND a.class_level=n.class_level AND a.subject=n.subject)) OR (n.note_type='central' AND n.school_id IS NULL AND EXISTS(SELECT 1 FROM teacher_assignments a JOIN school_memberships m ON m.school_id=a.school_id AND m.user_id=a.user_id JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects cs ON cs.class_id=c.id AND cs.name=a.subject LEFT JOIN academic_classes ac ON ac.name=n.class_level LEFT JOIN academic_class_subjects ats ON ats.class_id=ac.id AND ats.name=n.subject WHERE a.user_id=? AND a.active=1 AND (c.name=n.class_level OR (ac.id IS NOT NULL AND c.core_class_id=ac.id)) AND (n.subject IS NULL OR n.subject='' OR cs.name=n.subject OR (ats.id IS NOT NULL AND cs.core_subject_id=ats.id))))";$params=[$uid,$uid];if($class!==null){$sql.=" AND n.class_level=? AND (n.subject IS NULL OR n.subject='' OR n.subject=?)";$params[]=$class;$params[]=$subject??'';}$sql.=' ORDER BY n.note_type,n.subtopic LIMIT 300';$q=$pdo->prepare($sql);$q->execute($params);return $q->fetchAll(PDO::FETCH_ASSOC);}

if($_SERVER['REQUEST_METHOD']==='POST'){
