?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI question generator · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/ai-question-import.js"></script><script defer src="assets/ai-question-generate.js"></script></head><body><div class="app-shell"><?php require __DIR__ . "/sidebar.php"; ?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Academics <span>/</span> AI question generator</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??''))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">AI ASSESSMENT TOOLS</div><h1>Generate questions from notes</h1><p class="muted">Create a question set and answer key from accessible school notes.</p></div></section><?php if($savedMessage):?><div class="notice success" role="status">OpenRouter settings saved.</div><?php endif;?><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?>
<?php if($isManager):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">PROVIDER SETTINGS</div><h2>OpenRouter</h2><p class="muted">The API key is encrypted on the server and never shown after saving.</p></div></div><?php if(!function_exists('openssl_encrypt')):?><div class="notice error">Enable the PHP OpenSSL extension to store API keys securely.</div><?php elseif(strlen((string)getenv('SHULELITE_ENCRYPTION_KEY'))<32):?><div class="notice error">Set the server environment variable SHULELITE_ENCRYPTION_KEY to a random secret of at least 32 characters before saving a key.</div><?php endif;?><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_ai_settings"><p class="muted">Models are tried in this order. If one is unavailable, OpenRouter tries the next.</p><ol class="ai-model-order"><li><strong>Main:</strong> <code>openai/gpt-4o-mini</code></li><li>Claude Haiku · <code>~anthropic/claude-haiku-latest</code></li><li>Gemini · <code>google/gemini-3.8-flash</code></li><li>Kimi · <code>~moonshotai/kimi-latest</code></li><li>GLM · <code>~z-ai/glm-latest</code></li></ol><label for="openrouter-key">API key</label><input id="openrouter-key" name="api_key" type="password" autocomplete="new-password" placeholder="<?= $aiSettings?'Saved securely · enter a new key to replace it':'Enter OpenRouter API key' ?>" <?= $aiSettings?'':'required'?>><button class="button primary" type="submit">Save OpenRouter settings</button><?php if($aiSettings):?><small class="muted">Last updated <?=e(date('j M Y H:i',strtotime($aiSettings['updated_at'])))?>. The current key is not displayed.</small><?php endif;?></form></section><?php endif;?>
<section class="note-create"><div class="section-heading"><div><div class="eyebrow">QUESTION SET</div><h2>Build from notes</h2></div></div><?php if(!$aiSettings):?><div class="empty-hint">The AI provider is not configured yet. Ask a system admin or sub admin to set it up.</div><?php endif;?><form method="post" class="note-form" id="ai-question-generate-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="generate"><div class="form-grid"><div><label for="question-class">Class</label><input id="question-class" name="class_level" list="question-note-classes" maxlength="80" required value="<?=e($_POST['class_level']??'')?>"><datalist id="question-note-classes"><?php foreach($notes as $n):?><option value="<?=e($n['class_level'])?>"><?php endforeach;?></datalist></div><div><label for="question-subject">Subject</label><input id="question-subject" name="subject" list="question-note-subjects" maxlength="100" required value="<?=e($_POST['subject']??'')?>"><datalist id="question-note-subjects"><?php foreach($notes as $n):if($n['subject']):?><option value="<?=e($n['subject'])?>"><?php endif;endforeach;?></datalist></div><div><label for="question-topic">Topic</label><input id="question-topic" name="topic" maxlength="180" required value="<?=e($_POST['topic']??'')?>" placeholder="Topic covered in the notes"></div><div><label>Question sections</label><div id="question-sections" class="question-sections"><?php $postedSections=$_POST['sections']??[];if(!is_array($postedSections)||!$postedSections)$postedSections=[['style'=>'true_false','count'=>5]];foreach(array_values($postedSections) as $sectionIndex=>$section):?><div class="question-section-row"><select name="sections[<?=$sectionIndex?>][style]" aria-label="Question style"><?php foreach(['multiple_choice'=>'Multiple choice','true_false'=>'True or false','matching'=>'Matching items','short_answer'=>'Short answers (no word box)','short_answer_box'=>'Short answers (with word box)','paragraph'=>'Paragraph questions','explanation'=>'Explanations'] as $style=>$label):?><option value="<?=$style?>" <?=($section['style']??'true_false')===$style?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><input type="number" name="sections[<?=$sectionIndex?>][count]" min="1" max="100" value="<?=e((string)($section['count']??5))?>" aria-label="Questions in section" required><button type="button" class="button" data-remove-question-section aria-label="Remove this question section">Remove</button></div><?php endforeach;?></div><button type="button" class="button" id="add-question-section">Add section</button><small class="muted" id="question-section-total" aria-live="polite">0 of 100 questions selected</small></div><div><label for="difficulty">Difficulty</label><select id="difficulty" name="difficulty"><option value="mixed">Mixed</option><option value="easy">Easy</option><option value="moderate">Moderate</option><option value="challenging">Challenging</option></select></div></div><button class="button primary" type="submit" <?=!$aiSettings?'disabled':''?>>Generate questions</button><div id="ai-question-generate-status" class="notice" role="status" aria-live="polite" hidden></div></form></section><div id="ai-generated-results"><?php if($generated):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">GENERATED FROM <?=count($noteContext)?> NOTES</div><h2>Questions and answer key</h2></div><button class="button" type="button" onclick="navigator.clipboard.writeText(document.getElementById('generated-questions').innerText).then(()=>this.textContent='Copied')">Copy questions</button></div><pre id="generated-questions" class="ai-question-output"><?=e($generated)?></pre><?php if($importEligible&&$generatedQuestions&&$importSchools):?><div class="note-create" data-ai-question-import data-api="api/question_bank.php" data-csrf="<?=e(csrf_token())?>" data-topic="<?=e((string)($_POST['topic']??''))?>" data-import-key="<?=e($importBatchKey)?>" data-questions-id="ai-generated-question-data"><h3>Save as question-bank drafts</h3><p class="muted">AI questions are imported as editable drafts. They must be reviewed and published through the question bank before they can be used in an exam.</p><div class="form-grid"><div><label for="ai-import-school">School</label><select id="ai-import-school" required><option value="">Choose school</option><?php foreach($importSchools as $schoolOption):?><option value="<?=$schoolOption['id']?>"><?=e($schoolOption['name'])?></option><?php endforeach;?></select></div><div><label for="ai-import-class">Class</label><select id="ai-import-class" disabled required><option value="">Choose school first</option></select></div><div><label for="ai-import-subject">Subject</label><select id="ai-import-subject" disabled required><option value="">Choose class first</option></select></div><div><label for="ai-import-marks">Default marks per question</label><input id="ai-import-marks" type="number" min="0.25" max="1000" step="0.25" value="1" required></div></div><button class="button primary" type="button" data-ai-import-submit>Save editable drafts</button><div data-ai-import-status class="notice" role="status" aria-live="polite" hidden></div></div><script type="application/json" id="ai-generated-question-data"><?=json_encode(['questions'=>$generatedQuestions],JSON_THROW_ON_ERROR|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><?php elseif($generatedQuestions):?><p class="muted">Generated questions are ready to copy. Sign in with a school question-bank role and linked school to save drafts.</p><?php else:?><p class="muted">This response could not be structured for question-bank import. You can review and copy it, then create bank questions manually.</p><?php endif;?></section><?php endif;?></div><section class="content-section"><div class="section-heading"><div><div class="eyebrow">SOURCE NOTES</div><h2>Notes available to you</h2><p class="muted"><?=$isManager?'System admins and sub-admins can use school and teacher notes across the platform.':($role==='teacher'?'Teachers can use central and school notes matching their active class and subject assignments.':'You can use notes available to your role.')?></p></div><span class="count-pill"><?=count($notes)?> note topics</span></div><?php if(!$notes):?><p class="muted">No accessible notes are available yet.</p><?php else:?><div class="assignment-chip-list"><?php foreach($notes as $n):?><span class="assignment-chip"><?=e($n['class_level'])?><?= $n['subject']?' · '.e($n['subject']):' · General'?></span><?php endforeach;?></div><?php endif;?></section></div></main></div><style>.ai-question-output{white-space:pre-wrap;overflow-wrap:anywhere;padding:20px;border:1px solid var(--border);border-radius:12px;background:var(--surface);font-family:inherit;font-size:14px;line-height:1.7;color:var(--text)}</style><script>document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('#question-sections'),add=document.querySelector('#add-question-section'),summary=document.querySelector('#question-section-total');if(!list||!add)return;const styles=[['multiple_choice','Multiple choice'],['true_false','True or false'],['matching','Matching items'],['short_answer','Short answers (no word box)'],['short_answer_box','Short answers (with word box)'],['paragraph','Paragraph questions'],['explanation','Explanations']];const reindex=()=>[...list.children].forEach((row,index)=>{row.querySelector('select').name=`sections[${index}][style]`;row.querySelector('input').name=`sections[${index}][count]`});const sync=()=>{const total=[...list.querySelectorAll('input[type=number]')].reduce((sum,input)=>sum+(Number(input.value)||0),0);if(summary)summary.textContent=`${total} of 100 questions selected`;add.disabled=total>=100;list.querySelectorAll('input[type=number]').forEach(input=>input.setCustomValidity(total>100?'Sections can contain no more than 100 questions in total.':''))};const bind=()=>{list.querySelectorAll('[data-remove-question-section]').forEach(button=>button.onclick=()=>{if(list.children.length>1){button.closest('.question-section-row').remove();reindex();sync()}});list.querySelectorAll('input[type=number]').forEach(input=>input.oninput=sync)};add.addEventListener('click',()=>{const i=list.children.length,row=document.createElement('div');row.className='question-section-row';const select=document.createElement('select');select.name=`sections[${i}][style]`;select.setAttribute('aria-label','Question style');styles.forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;select.append(option)});const count=document.createElement('input');count.type='number';count.min='1';count.max='100';count.value=String(Math.max(1,Math.min(5,100-[...list.querySelectorAll('input[type=number]')].reduce((sum,input)=>sum+(Number(input.value)||0),0))));count.name=`sections[${i}][count]`;count.required=true;count.setAttribute('aria-label','Questions in section');const remove=document.createElement('button');remove.type='button';remove.className='button';remove.textContent='Remove';remove.setAttribute('aria-label','Remove this question section');remove.dataset.removeQuestionSection='';row.append(select,count,remove);list.append(row);bind();sync()});bind();sync()});</script><style>.form-grid>div:has(#question-sections){grid-column:1/-1;min-width:0}.question-sections{display:grid;gap:8px;margin:8px 0;min-width:0;container-type:inline-size}.question-section-row{display:grid;grid-template-columns:minmax(0,1fr) 84px auto;gap:8px;align-items:center;min-width:0}.question-section-row>*{min-width:0}.question-section-row select,.question-section-row input{width:100%;min-height:42px;padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text)}.question-section-row .button{min-width:0;padding-inline:12px}@container (max-width:520px){.question-section-row{grid-template-columns:minmax(0,1fr) 76px}.question-section-row .button{grid-column:1/-1;justify-self:start;width:auto}}</style></body></html>
